def f(g, mode='down'):
    h,w=len(g),len(g[0])
    bg=g[0][0]
    cnt={}
    for r in g:
        for c in r:
            if c!=bg: cnt[c]=cnt.get(c,0)+1
    col=max(cnt,key=lambda k:cnt[k])
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    if mode=='down':
        for i in range(h):
            for j in range(w):
                if g[i][j]==col: out[(i+1)%h][j]=col
    return out
